#!/usr/bin/env python3
"""What `post_check.py` claims about a draft body, as tests.

Run: python3 -m unittest discover -s .agents/skills/post-check -p 'test_*.py'
"""
import contextlib
import io
import pathlib
import shutil
import subprocess
import tempfile
import unittest
import unittest.mock

import post_check

SETUP = {"USER": "owner", "AGENT": "owner-bot", "AGENT_EMAIL": "bot@example.test",
         "WORK_REPOS": ["org/open", "org/secret"], "MEMORY_REPO": "owner/memory",
         "AGENT_FOOTERS": ["example.test/agent", "Generated by Test Harness"]}


def closes(text, default="org/open"):
    return post_check.closes(post_check.prose(text), default)


class Closing(unittest.TestCase):
    """One keyword, one reference, on one line."""

    def test_one_keyword_per_reference_links_each(self):
        findings, keys = closes("Closes #1\nfixes org/other#2\n"
                                "Resolves https://github.com/org/x/issues/3")
        self.assertEqual(findings, [])
        self.assertEqual(keys, ["org/open#1", "org/other#2", "org/x#3"])

    def test_a_list_after_one_keyword_is_a_finding(self):
        for text in ("Closes #1, #2", "Closes #1 and #2", "Fixes #1 #2 #3"):
            with self.subTest(text=text):
                findings, keys = closes(text)
                self.assertEqual(len(findings), 1)
                self.assertEqual(keys, ["org/open#1"])

    def test_a_keyword_per_reference_on_one_line_is_fine(self):
        self.assertEqual(closes("Closes #1, closes #2")[1],
                         ["org/open#1", "org/open#2"])

    def test_a_reference_on_the_next_line_is_a_finding(self):
        for text in ("Closes\n#4", "Resolves:\n- #4", "Fixes these:\n\n1. #4"):
            with self.subTest(text=text):
                findings, keys = closes(text)
                self.assertIn("next line", findings[0])
                self.assertEqual(keys, [])

    def test_a_short_repo_name_is_a_finding(self):
        self.assertIn("owner/repo#N", closes("Closes wiki#4")[0][0])

    def test_prose_and_code_are_not_closing_references(self):
        text = ("#808 closed unmerged, fixed in #12.\nThis fixed the bug.\n"
                "`Closes #9, #10`\n```\nCloses #1, #2\n```\nclosed-loop #3")
        self.assertEqual(closes(text), ([], []))

    def test_a_colon_is_allowed(self):
        self.assertEqual(closes("Fixes: #7"), ([], ["org/open#7"]))


class Mentions(unittest.TestCase):
    """The first mention of each item, with its words around it."""

    def test_first_mention_only_with_context(self):
        lines = post_check.prose("See #5 (the bug) and org/x#5.\nAgain #5.")
        found = list(post_check.mentions(lines, "org/open", words=2))
        self.assertEqual(found, [(1, "#5", "See #5 (the bug)"),
                                 (1, "org/x#5", "bug) and org/x#5.")])

    def test_anchors_and_entities_are_not_items(self):
        lines = post_check.prose("[x](OPS.md#reading-ci) &#123; a/b/pull/3#r9")
        self.assertEqual(list(post_check.mentions(lines, "org/open")), [])


class Footer(unittest.TestCase):
    """Exactly one marker on the last line, as sweep reads it."""

    def test_one_marker_on_the_last_line_is_clean(self):
        for body in ("Done.\n\nGenerated by Test Harness\n\n",
                     "Done.\n_Generated by [Harness](https://example.test/agent)_"):
            with self.subTest(body=body):
                self.assertEqual(post_check.footer(body, SETUP), [])

    def test_no_marker_or_a_link_label_is_a_finding(self):
        for body in ("Done.", "Done.\n[Generated by Test Harness](https://x.test)",
                     "Done.\nhttps://example.test/agent/session"):
            with self.subTest(body=body):
                self.assertIn("0 AGENT_FOOTERS", post_check.footer(body, SETUP)[0])

    def test_two_markers_or_two_footers_are_findings(self):
        two = "x\n[a](https://example.test/agent) [b](https://example.test/agent/2)"
        self.assertIn("2 AGENT_FOOTERS", post_check.footer(two, SETUP)[0])
        stacked = "x\nGenerated by Test Harness\n\n_by [H](https://example.test/agent)_"
        self.assertIn("earlier", post_check.footer(stacked, SETUP)[0])

    def test_a_link_in_prose_is_not_an_earlier_footer(self):
        body = ("See [the session](https://example.test/agent/1) for the run log.\n"
                "Generated by Test Harness")
        self.assertEqual(post_check.footer(body, SETUP), [])

    def test_an_empty_body_is_a_finding(self):
        self.assertEqual(len(post_check.footer(" \n", SETUP)), 1)


class Leaks(unittest.TestCase):
    """Private repos and denylist hits, for a public target."""

    def test_named_reads_full_and_short_forms(self):
        self.assertTrue(post_check.named("org/secret", "see Org/Secret today"))
        self.assertTrue(post_check.named("org/secret", "see secret#4"))
        self.assertFalse(post_check.named("org/secret", "a secret plan"))
        self.assertFalse(post_check.named("org/secret", "org/secret-two"))

    def test_private_and_unreadable_are_findings_public_is_not(self):
        lines = ["org/open#1", "org/secret", "owner/memory#2", "fine"]
        visibility = {"org/open": True, "org/secret": False,
                      "owner/memory": "HTTP 403"}
        found = post_check.leaks(lines, "body", visibility, [])
        self.assertEqual(len(found), 2)
        self.assertIn("unreadable (HTTP 403)", found[1])

    def test_denylist_skips_comments_and_matches_lines(self):
        with tempfile.NamedTemporaryFile("w", suffix=".txt") as file:
            file.write("# amounts\n\n\\$\\d+k\n(?i)partner\n")
            file.flush()
            patterns = post_check.denylist(file.name)
        found = post_check.leaks(["raised $50k", "a Partner", "ok"], "body", {},
                                 patterns)
        self.assertEqual([f.split(":")[1] for f in found],
                         [" body line 1", " body line 2"])


class Identity(unittest.TestCase):
    """Commit authors and signatures."""

    entries = [("a" * 40, "owner-bot", "bot@example.test", "G", ""),
               ("b" * 40, "someone", "me@x.test", "N", ""),
               ("c" * 40, "owner-bot", "bot@example.test", "B", "")]

    def test_author_and_bad_signature_are_findings_unsigned_a_note(self):
        found, notes = post_check.identity(self.entries, SETUP, signed=False)
        self.assertEqual(len(found), 2)
        self.assertEqual(notes, ["unsigned: 1 commits: bbbbbbb"])

    def test_signed_makes_unsigned_a_finding(self):
        found, notes = post_check.identity(self.entries, SETUP, signed=True)
        self.assertEqual((len(found), notes), (3, []))

    @unittest.skipUnless(shutil.which("git"), "no git")
    def test_commits_reads_a_range(self):
        with tempfile.TemporaryDirectory() as tmp:
            def git(*args):
                subprocess.run(["git", "-C", tmp, "-c", "user.name=owner-bot",
                                "-c", "user.email=bot@example.test",
                                "-c", "commit.gpgsign=false", *args],
                               check=True, capture_output=True)
            git("init", "-q")
            git("commit", "-q", "--allow-empty", "-m", "base")
            git("commit", "-q", "--allow-empty", "-m", "names org/secret\n\nbody")
            entries = post_check.commits(tmp, "HEAD~1..HEAD")
            self.assertEqual([e[1:4] for e in entries],
                             [("owner-bot", "bot@example.test", "N")])
            self.assertIn("org/secret", entries[0][4])
            with self.assertRaises(post_check.Unread):
                post_check.commits(tmp, "nope..HEAD")


class Verify(unittest.TestCase):
    """GitHub's closing references against the body's keywords."""

    def test_compare_reports_both_directions(self):
        found = post_check.compare({"org/open#1", "org/open#3"},
                                   ["Org/Open#1", "org/open#2"])
        self.assertEqual(found, [
            "verify: GitHub links org/open#3, the body names no keyword for it",
            "verify: the body closes org/open#2, GitHub does not link it"])


class Config(unittest.TestCase):
    """config.env read like sweep's."""

    def test_lists_split_and_comments_skipped(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = pathlib.Path(tmp) / "config.env"
            path.write_text("# seed\nUSER=a\nWORK_REPOS=o/a, o/b\n"
                            "AGENT_FOOTERS=x, ,y\n")
            setup = post_check.config(path)
            self.assertEqual(setup["WORK_REPOS"], ["o/a", "o/b"])
            self.assertEqual(setup["AGENT_FOOTERS"], ["x", "y"])
            path.write_text("no key here\n")
            with self.assertRaises(ValueError):
                post_check.config(path)


class Main(unittest.TestCase):
    """Exit codes end to end, with no GitHub read."""

    def run_main(self, body, *extra):
        with tempfile.TemporaryDirectory() as tmp:
            config = pathlib.Path(tmp) / "config.env"
            config.write_text("AGENT=owner-bot\nWORK_REPOS=org/open,org/secret\n"
                              "AGENT_FOOTERS=Generated by Test Harness\n")
            draft = pathlib.Path(tmp) / "body.md"
            draft.write_text(body)
            with contextlib.redirect_stdout(io.StringIO()) as out:
                code = post_check.main([str(draft), "--target", "org/open",
                                        "--public", "org/open", "--config",
                                        str(config), *extra])
            return code, out.getvalue()

    def test_clean_body_exits_zero(self):
        code, out = self.run_main("Closes #1\n\nGenerated by Test Harness")
        self.assertEqual((code, out.splitlines()[-1]), (0, "clean"))
        self.assertIn("first mention: line 1: #1", out)

    def test_findings_exit_one(self):
        self.assertEqual(self.run_main("Closes #1, #2")[0], 1)

    def test_a_private_repo_in_code_is_still_a_leak(self):
        code, out = self.run_main("`org/secret#1`\n```\norg/secret\n```\n"
                                  "Generated by Test Harness", "--public",
                                  "org/secret", "--denylist", "/dev/null")
        self.assertEqual(code, 0)
        with unittest.mock.patch.object(post_check, "is_public",
                                        return_value=False):
            code, out = self.run_main("`org/secret#1`\n```\norg/secret\n```\n"
                                      "Generated by Test Harness")
        self.assertEqual(code, 1)
        self.assertIn("body line 1: names org/secret", out)
        self.assertIn("body line 3: names org/secret", out)

    def test_a_missing_body_exits_two(self):
        with contextlib.redirect_stdout(io.StringIO()) as out:
            code = post_check.main(["/nonexistent/body.md", "--target", "o/r",
                                    "--config", "/nonexistent/config.env"])
        self.assertEqual((code, out.getvalue().splitlines()[-1]),
                         (2, "incomplete"))

    def test_unreadable_denylist_exits_two(self):
        code, out = self.run_main("ok\nGenerated by Test Harness",
                                  "--denylist", "/nonexistent/deny.txt")
        self.assertEqual((code, out.splitlines()[-1]), (2, "incomplete"))


if __name__ == "__main__":
    unittest.main()
